def magic_square_test(matrix):
    # Check if matrix is square
    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False

    # Check if matrix contains numbers from 1 to n^2 exactly once
    expected_numbers = set(range(1, n * n + 1))
    actual_numbers = set()
    for row in matrix:
        for num in row:
            actual_numbers.add(num)

    if actual_numbers != expected_numbers:
        return False

    # Calculate magic constant
    magic_constant = n * (n * n + 1) // 2

    # Check row sums
    for row in matrix:
        if sum(row) != magic_constant:
            return False

    # Check column sums
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != magic_constant:
            return False

    # Check main diagonal
    main_diagonal = sum(matrix[i][i] for i in range(n))
    if main_diagonal != magic_constant:
        return False

    # Check anti-diagonal
    anti_diagonal = sum(matrix[i][n - 1 - i] for i in range(n))
    if anti_diagonal != magic_constant:
        return False

    return True


