        return 0

    n = len(arr)

    # LIS[i] = maximum sum of increasing subsequence ending at index i
    LIS = [0] * n
    for i in range(n):
        LIS[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                LIS[i] = max(LIS[i], LIS[j] + arr[i])

    # LDS[i] = maximum sum of decreasing subsequence starting at index i
    LDS = [0] * n
    for i in range(n - 1, -1, -1):
        LDS[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                LDS[i] = max(LDS[i], LDS[j] + arr[i])

    # Find maximum bitonic sum
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, LIS[i] + LDS[i] - arr[i])

    return max_sum

